import React, { useRef, useState } from "react";
import MonacoEditor from "@monaco-editor/react";
import Plotly from "plotly.js-dist-min";
import * as THREE from "three";
import "./CodeEditorPortal.css";

let pyodideReadyPromise = null;
let pyodideInstance = null;

async function loadPyodideIfNeeded() {
  if (!pyodideInstance) {
    if (!pyodideReadyPromise) {
      pyodideReadyPromise = window.loadPyodide();
    }
    pyodideInstance = await pyodideReadyPromise;
  }
  return pyodideInstance;
}

export default function CodeEditorPortal({ language, code, setCode }) {
  const [output, setOutput] = useState("");
  const [consoleOutput, setConsoleOutput] = useState("");
  const plotRef = useRef(null);
  const editorRef = useRef(null);

  function handleEditorDidMount(editor) {
    editorRef.current = editor;
  }

  async function runCode() {
    let result = "";
    let consoleLogs = [];

    // Always clear previous plot output and force a reflow
    if (plotRef.current) {
      plotRef.current.innerHTML = "";
      plotRef.current.style.display = "none";
      setTimeout(() => {
        if (plotRef.current) plotRef.current.style.display = "block";
      }, 0);
    }

    if (language === "python") {
      setOutput("Running Python...");
      setConsoleOutput("");
      const pyodide = await loadPyodideIfNeeded();
      try {
        await pyodide.loadPackage("matplotlib");
        await pyodide.runPythonAsync(`
import sys
from io import StringIO
sys.stdout = sys.stderr = mystdout = StringIO()
`);
        await pyodide.runPythonAsync(`
import matplotlib.pyplot as plt
plt.ioff()
`);
        await pyodide.runPythonAsync(code);

        // Extract SVG from matplotlib
        let svg = "";
        try {
          svg = await pyodide.runPythonAsync(`
import matplotlib.pyplot as plt
import io
buf = io.StringIO()
plt.gcf().savefig(buf, format="svg")
svg_output = buf.getvalue()
buf.close()
svg_output
`);
        } catch (e) {
          svg = "";
        }
        console.log("Extracted SVG:", svg);
        // Get stdout
        let textOutput = "";
        try {
          textOutput = await pyodide.runPythonAsync("mystdout.getvalue()");
        } catch (e) {
          textOutput = "";
        }

        // Render SVG in plot output block and ensure it fills the block
        if (svg && typeof svg === "string" && svg.includes("<svg")) {
          if (plotRef.current) {
            // Remove XML and DOCTYPE headers for safer rendering
            let cleanedSVG = svg.replace(/<\?xml[\s\S]*?\?>/i, "")
                                .replace(/<!DOCTYPE[\s\S]*?>/i, "");
            // Defensive: Remove any leading whitespace before <svg
            cleanedSVG = cleanedSVG.trim().replace(/^[\s\S]*?(<svg[\s\S]*<\/svg>)/i, "$1");
            plotRef.current.innerHTML = cleanedSVG;
            // Force SVG to fill container
            const svgElem = plotRef.current.querySelector("svg");
            if (svgElem) {
              svgElem.setAttribute("width", "100%");
              svgElem.setAttribute("height", "100%");
              svgElem.style.width = "100%";
              svgElem.style.height = "100%";
              svgElem.style.display = "block";
            }
            // Debug: confirm SVG is in DOM
            console.log("SVG element in DOM:", svgElem);
          }
          setOutput(""); // Output block only for text/errors
        } else if (textOutput) {
          setOutput(textOutput);
        } else {
          setOutput("No output.");
        }
        setConsoleOutput("");
      } catch (err) {
        setOutput(err.toString());
        setConsoleOutput("");
        if (plotRef.current) plotRef.current.innerHTML = "";
        console.log("Python error:", err);
      }
      return;
    }

    if (language !== "javascript") {
      result = `Code execution is only supported for JavaScript and Python.`;
      setOutput(result);
      setConsoleOutput("");
      if (plotRef.current) plotRef.current.innerHTML = "";
      return;
    }

    // JavaScript execution
    const originalConsoleLog = window.console.log;
    window.console.log = (...args) => {
      consoleLogs.push(args.join(" "));
      originalConsoleLog(...args);
    };

    try {
      // Provide access to the output div, THREE, and Plotly in the eval context
      // eslint-disable-next-line no-new-func
      const func = new Function("THREE", "outputDiv", "Plotly", code);
      func(THREE, plotRef.current, Plotly); // Pass imported THREE here
      result = "Code executed.";
    } catch (err) {
      result = err.toString();
    }
    window.console.log = originalConsoleLog;
    setOutput(result === undefined ? "" : String(result));
    setConsoleOutput(consoleLogs.join("\n"));
  }

  return (
    <div>
      <MonacoEditor
        height="300px"
        language={language}
        value={code}
        onChange={setCode}
        onMount={handleEditorDidMount}
        options={{ fontSize: 16 }}
      />
      <button onClick={runCode}>Run Code</button>
      <div style={{ display: "flex", gap: "24px", marginTop: "16px" }}>
        <div style={{ flex: 1 }}>
          <h3>Output:</h3>
          <div style={{ minWidth: 200, minHeight: 100, marginBottom: 16 }}>
            {output}
          </div>
          <div
            ref={plotRef}
            id="plot-output"
            style={{
              width: "100%",
              minHeight: 300,
              maxHeight: 500,
              border: "1px solid #333",
              background: "#fff",
              borderRadius: "8px",
              boxShadow: "0 2px 8px rgba(0,0,0,0.07)",
              padding: "12px",
              overflow: "auto",
              position: "relative"
            }}
          ></div>
        </div>
      </div>
      <div style={{ marginTop: "16px" }}>
        <h3>Console:</h3>
        <pre style={{ minHeight: 80 }}>{consoleOutput}</pre>
      </div>
    </div>
  );
}